CREATE SEQUENCE public."ComplexStatsCache_id_seq";
CREATE TABLE public."ComplexStatsCache" (id bigint DEFAULT nextval('public."ComplexStatsCache_id_seq"'::regclass) NOT NULL, group_id bigint NOT NULL, species_id bigint NOT NULL, temporal_unit text NOT NULL, time_period date NOT NULL, new_adult_bird_count bigint NOT NULL, returning_age_1_bird_count bigint NOT NULL, returning_age_2_bird_count bigint NOT NULL, returning_age_3_plus_bird_count bigint NOT NULL, returning_new_unknown_age_bird_count bigint NOT NULL);
ALTER SEQUENCE public."ComplexStatsCache_id_seq" OWNED BY public."ComplexStatsCache".id;
GRANT UPDATE ON SEQUENCE public."ComplexStatsCache_id_seq" TO anon;
GRANT UPDATE ON SEQUENCE public."ComplexStatsCache_id_seq" TO authenticated;
GRANT UPDATE ON SEQUENCE public."ComplexStatsCache_id_seq" TO service_role;
COMMENT ON TABLE public."ComplexStatsCache" IS 'One row per (group_id, species_id, temporal_unit, time_period): the lifetime-relative demographics_stats_result metrics (new_adult_bird_count and the four returning_age_* columns), which read a bird''s whole unwindowed history and so must be fully replaced on refresh rather than narrowed to affected dates. Period-local metrics live in the separate SimpleStatsCache table instead.';
COMMENT ON COLUMN public."ComplexStatsCache".time_period IS 'Sentinel value 0001-01-01 for the all-time grain, never real data. This table uses a fixed sentinel instead of NULL (unlike demographics_stats) so a single plain UNIQUE constraint covers every grain.';
ALTER TABLE public."ComplexStatsCache" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."ComplexStatsCache" ADD CONSTRAINT "ComplexStatsCache_pkey" PRIMARY KEY (id);
ALTER TABLE public."ComplexStatsCache" ADD CONSTRAINT complex_stats_cache_group_id_fkey FOREIGN KEY (group_id) REFERENCES public."RingingGroups"(id);
ALTER TABLE public."ComplexStatsCache" ADD CONSTRAINT complex_stats_cache_group_species_grain_period_key UNIQUE (group_id, species_id, temporal_unit, time_period);
ALTER TABLE public."ComplexStatsCache" ADD CONSTRAINT complex_stats_cache_species_id_fkey FOREIGN KEY (species_id) REFERENCES public."Species"(id);
ALTER TABLE public."ComplexStatsCache" ADD CONSTRAINT complex_stats_cache_temporal_unit_check CHECK (temporal_unit = ANY (ARRAY['day'::text, 'month'::text, 'year'::text, 'month-squashed'::text, 'all-time'::text]));
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public."ComplexStatsCache" TO anon;
GRANT INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON public."ComplexStatsCache" TO authenticated;
GRANT ALL ON public."ComplexStatsCache" TO service_role;
CREATE INDEX idx_complex_stats_cache_group_id ON public."ComplexStatsCache" (group_id);
CREATE POLICY group_complex_stats_cache_access ON public."ComplexStatsCache" FOR SELECT USING ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint));
CREATE POLICY group_complex_stats_cache_insert ON public."ComplexStatsCache" FOR INSERT WITH CHECK ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint));
CREATE POLICY group_complex_stats_cache_update ON public."ComplexStatsCache" FOR UPDATE USING ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint)) WITH CHECK ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint));
